css:
[data-bz-node="ns"] { position: relative; z-index: 3; max-width: 1180px; margin: 0; padding: 80px 40px 40px clamp(40px, 7vw, 120px); }
[data-bz-node="ns-heading"] { margin: 0 0 34px; }
[data-bz-section="news-stories"] .bz-eyebrow { display: block; font-family: var(--font-heading); font-weight: 400; font-size: 13px; letter-spacing: .3em; color: #00cdfd; margin: 0; padding-top: 3px; line-height: 16px; }
[data-bz-section="news-stories"] [data-bz-node="ns-heading"] h2 { font-weight: 600; font-size: clamp(36px, 5vw, 64px); line-height: .95; margin: 8px 0 0; color: #eaf2f8; }
[data-bz-node="ns-grid"] { display: grid; grid-template-columns: 1.4fr 1fr; gap: 22px; align-items: stretch; }
[data-bz-node="ns-grid"] > .bz-col { grid-column: auto; }
/* featured story */
[data-bz-node="ns-feature"] { position: relative; border-radius: 16px; overflow: hidden; border: 1px solid rgba(255,255,255,.08); min-height: 440px; display: flex; flex-direction: column; justify-content: flex-end; padding: 36px; transition: border-color .3s ease; background: #020617; }
[data-bz-node="ns-feature"]:hover { border-color: rgba(0,205,253,.4); }
[data-bz-node="ns-feature"]::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(2,6,23,.1) 30%, rgba(2,6,23,.95)); pointer-events: none; }
[data-bz-node="ns-feature"] > * { position: relative; z-index: 2; margin: 0; }
[data-bz-node="ns-feature"] > .bz-block:first-child { position: absolute; inset: 0; z-index: 0; }
[data-bz-node="ns-feature"] > .bz-block:first-child :is(figure, img, .bz-photo) { width: 100%; height: 100%; object-fit: cover; border-radius: 0; margin: 0; }
[data-bz-node="ns-feature"] .bz-photo--empty { font-size: 0; border: 0; min-height: 100%; background: repeating-linear-gradient(135deg, rgba(255,255,255,.045) 0 10px, rgba(255,255,255,.015) 10px 20px); }
[data-bz-node="ns-feature-tag"].bz-block p { position: relative; width: fit-content; margin: 0; padding: 4px 11px 0; font-family: var(--font-heading); font-weight: 600; font-size: 11px; line-height: 15px; letter-spacing: .16em; text-transform: uppercase; color: #020617; }
[data-bz-node="ns-feature-tag"].bz-block p::before { content: ""; position: absolute; left: 0; right: 0; top: 2px; height: 20px; background: linear-gradient(135deg, #d705dd, #7a2bd6); border-radius: 4px; z-index: -1; }
[data-bz-node="ns-feature-tag"] { isolation: isolate; }
[data-bz-node="ns-feature-title"] h3 { font-weight: 600; font-size: clamp(26px, 3vw, 40px); line-height: 1.02; color: #fff; margin: 18px 0 0; }
[data-bz-node="ns-feature-dek"].bz-block p { color: #b3c4d3; font-size: 15px; font-weight: 300; line-height: 1.5; margin: 12px 0 0; max-width: 560px; }
[data-bz-node="ns-feature-meta"].bz-block p { display: block; margin: 14px 0 0; padding-bottom: 2px; font-size: 12px; line-height: 14px; letter-spacing: .14em; text-transform: uppercase; color: #6f8498; }
/* story rows */
[data-bz-node="ns-list"] { display: flex; flex-direction: column; gap: 16px; }
[data-bz-node="ns-list"] > .bz-row { display: flex; align-items: stretch; gap: 16px; padding: 16px; border-radius: 12px; border: 1px solid rgba(255,255,255,.07); background: rgba(6,12,28,.55); transition: transform .28s ease, border-color .28s ease; }
[data-bz-node="ns-list"] > .bz-row:hover { transform: translateX(4px); border-color: rgba(0,205,253,.4); }
[data-bz-node="ns-list"] > .bz-row > .bz-col:first-child { flex: none; width: 96px; max-width: 96px; }
[data-bz-node="ns-list"] > .bz-row > .bz-col:last-child { flex: 1 1 auto; width: auto; min-width: 0; }
[data-bz-node^="ns-story-thumb"] img, [data-bz-node^="ns-story-thumb"] .bz-photo { display: block; width: 96px; height: 96px; object-fit: cover; border-radius: 8px; }
[data-bz-section="news-stories"] .bz-photo--empty { font-size: 0; border: 0; background: repeating-linear-gradient(135deg, rgba(255,255,255,.045) 0 10px, rgba(255,255,255,.015) 10px 20px); outline: 1px dashed rgba(255,255,255,.18); outline-offset: -1px; }
[data-bz-node^="ns-story-cat"].bz-block p { margin: 0; padding-top: 4px; font-family: var(--font-heading); font-weight: 400; font-size: 11px; line-height: 15px; letter-spacing: .14em; text-transform: uppercase; color: #d705dd; }
[data-bz-node="ns-list"] > .bz-row:nth-of-type(2) [data-bz-node^="ns-story-cat"].bz-block p { color: #00cdfd; }
[data-bz-node="ns-list"] > .bz-row:nth-of-type(3) [data-bz-node^="ns-story-cat"].bz-block p { color: #00fbff; }
[data-bz-node^="ns-story-title"] h4 { font-family: var(--font-body); font-weight: 600; font-size: 17px; line-height: 1.2; letter-spacing: 0; text-transform: none; color: #eaf2f8; margin: 6px 0 8px; }
[data-bz-node^="ns-story-date"].bz-block p { margin: 0; font-size: 12px; line-height: 22px; letter-spacing: .1em; text-transform: uppercase; color: #6f8498; }
@media (max-width: 900px) { [data-bz-node="ns-grid"] { grid-template-columns: 1fr; } }
@media (max-width: 640px) { [data-bz-node="ns"] { padding: 60px 40px 30px; } [data-bz-node="ns-feature"] { min-height: 360px; padding: 24px; } }
